		margin-left: calc(-1 * var(--pad));
		margin-right: calc(-1 * var(--bleed-end, var(--pad)));
		padding-top: var(--divide);
		padding-left: var(--pad);
		padding-right: var(--bleed-end, var(--pad));
		border-top: var(--rule);
